def _clock_start(stop: StopTimes) -> datetime:
    """When free time starts counting for a stop: the later of check-in and appointment.

    A driver who checks in early waits on their own time until the appointment, so
    that early wait is not billable to the customer. Check-in still governs when the
    driver arrives after the appointment, and at FCFS facilities (no appointment) the
    check-in is the only timestamp available, so it is used there.
    """
    if stop.appointment is None:
        return stop.arrived
    return max(stop.arrived, stop.appointment)

