def _floor_positions_by_footprint(lines: list[PalletLine]) -> dict[tuple[int, int], int]:
    """Floor positions per footprint, pooling identical builds across BOL lines.

    Lines with the same build stack together, and lines with the same footprint
    share rows, so the total trailer length does not depend on how the shipper
    split the pallets across BOL lines.
    """
    counts: dict[tuple[int, int, int, bool], int] = {}
    for line in lines:
        key = (line.length_in, line.width_in, line.height_in, line.stackable)
        counts[key] = counts.get(key, 0) + line.count
    positions: dict[tuple[int, int], int] = {}
    for (length_in, width_in, height_in, stackable), count in counts.items():
        merged = PalletLine(count, length_in, width_in, height_in, stackable)
        positions[merged.footprint] = positions.get(merged.footprint, 0) + _floor_positions(merged)
    return positions


def _row_inches(lines: list[PalletLine]) -> int:
    """Total trailer length in inches, packing each footprint's floor positions into rows."""
    total = 0
    for (length_in, width_in), positions in _floor_positions_by_footprint(lines).items():
        total += math.ceil(positions / _per_row(width_in)) * length_in
    return total

